package com.acme.insurance.claims;

import java.time.LocalDate;

/**
 * Blocks claim registration when the underlying policy is no longer in force.
 */
public class PolicyInForceGuard {

    private final PolicyRepository policies;

    public PolicyInForceGuard(PolicyRepository policies) {
        this.policies = policies;
    }

    public void assertInForce(String policyNumber, LocalDate lossDate) {
        Policy p = policies.require(policyNumber);
        if (p.getStatus() == PolicyStatus.CANCELLED) {
            throw new PolicyNotInForceException(policyNumber, "cancelled");
        }
        if (lossDate.isAfter(p.getCoverEndDate()) || lossDate.isBefore(p.getCoverStartDate())) {
            throw new PolicyNotInForceException(policyNumber, "loss outside cover period");
        }
    }
}

class PolicyNotInForceException extends RuntimeException {
    public PolicyNotInForceException(String policy, String reason) {
        super("Policy " + policy + " not in force: " + reason);
    }
}

