package com.acme.insurance.settlement;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Computes a claim payout from assessed loss, excess and sum insured.
 */
public class ClaimPayoutCalculator {

    private final PolicyRepository policies;

    public ClaimPayoutCalculator(PolicyRepository policies) {
        this.policies = policies;
    }

    public Payout calculate(Claim claim) {
        Policy policy = policies.require(claim.getPolicyNumber());
        BigDecimal assessed = claim.getAssessedLoss();
        BigDecimal excess = policy.getExcess();
        BigDecimal afterExcess = assessed.subtract(excess).max(BigDecimal.ZERO);
        BigDecimal capped = afterExcess.min(policy.getSumInsured());
        return new Payout(assessed, excess, capped.setScale(2, RoundingMode.HALF_UP));
    }
}

