import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Claim registration endpoint: validate, attach documents, record as REGISTERED.
 */
@RestController
public class ClaimRegistrationController {

    private final PolicyInForceGuard inForce;
    private final EvidenceStorageService evidence;
    private final ClaimRepository claims;

    public ClaimRegistrationController(PolicyInForceGuard inForce,
                                       EvidenceStorageService evidence,
                                       ClaimRepository claims) {
        this.inForce = inForce;
        this.evidence = evidence;
        this.claims = claims;
    }

    @PostMapping("/claims")
    public ClaimView register(@RequestBody ClaimRegistrationRequest req) {
        inForce.assertInForce(req.getPolicyNumber(), req.getLossDate());
        if (req.getIncidentDescription() == null || req.getIncidentDescription().isBlank()) {
            throw new IllegalArgumentException("Incident description is required");
        }
        String evidenceKey = evidence.store(req.getDocuments());
        Claim claim = Claim.registered(req, evidenceKey);
        return ClaimView.from(claims.save(claim));
    }
}

