package com.acme.insurance.workflow;

import java.math.BigDecimal;

/**
 * Routes a newly registered claim to an assessor queue.
 */
public class ClaimRoutingService {

    private final QueueRepository queues;

    public ClaimRoutingService(QueueRepository queues) {
        this.queues = queues;
    }

    public String routeTo(Claim claim) {
        String band = bandFor(claim.getAssessedLoss());
        String queueName = claim.getClaimType() + "_" + band;
        if (!queues.exists(queueName)) {
            throw new IllegalStateException("No assessor queue configured for " + queueName);
        }
        return queueName;
    }

    private String bandFor(BigDecimal amount) {
        if (amount.compareTo(new BigDecimal("1000")) < 0) return "LOW";
        if (amount.compareTo(new BigDecimal("10000")) < 0) return "MEDIUM";
        return "HIGH";
    }
}

