package com.acme.insurance.decision;

import java.time.Instant;

/**
 * Records a claim decision and triggers the appropriate downstream action.
 */
public class ClaimDecisionService {

    private final ClaimRepository claims;
    private final NotificationGateway notifier;
    private final SettlementTrigger settlements;

    public ClaimDecisionService(ClaimRepository claims, NotificationGateway notifier, SettlementTrigger settlements) {
        this.claims = claims;
        this.notifier = notifier;
        this.settlements = settlements;
    }

    public void decide(String claimId, DecisionType decision, String assessorId, String note) {
        Claim c = claims.require(claimId);
        c.applyDecision(decision, assessorId, note, Instant.now());
        claims.save(c);
        switch (decision) {
            case APPROVED -> settlements.startSettlement(c);
            case DECLINED -> notifier.send(c.getClaimantId(), "Your claim has been declined: " + note);
            case REFERRED -> notifier.send(c.getClaimantId(), "Your claim has been referred for review");
        }
    }
}

