package com.acme.insurance.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists immutable audit rows for changes to claim decisions and amounts.
 */
public class ClaimChangeAuditor {

    private final EntityManager em;

    public ClaimChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String claimId, String field, String oldValue, String newValue, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            ClaimChangeEntry e = new ClaimChangeEntry();
            e.setClaimId(claimId);
            e.setField(field);
            e.setOldValue(oldValue);
            e.setNewValue(newValue);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

