package com.acme.insurance.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises claim decisions by handler assignment or supervisor override.
 */
public class ClaimDecisionAuthorisation {

    private final ClaimRepository claims;
    private final StaffDirectory staff;

    public ClaimDecisionAuthorisation(ClaimRepository claims, StaffDirectory staff) {
        this.claims = claims;
        this.staff = staff;
    }

    public void assertMayDecide(String userId, String claimId) {
        Claim c = claims.require(claimId);
        if (userId.equals(c.getAssignedAssessorId())) {
            return;
        }
        if (staff.hasRole(userId, "SUPERVISOR") && staff.hasOverrideFor(userId, claimId)) {
            return;
        }
        throw new AccessDeniedException("User " + userId + " may not decide claim " + claimId);
    }
}

