#include <stdio.h>
#include "insurance_db.h"

int write_settlement_file(const char *period, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "claim_reference,payee_account,amount\n");

    db_cursor_t *cur = NULL;
    if (db_open_approved_claims_cursor(&cur, period) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    claim_row_t row;
    while (db_claim_cursor_next(cur, &row) == DB_OK) {
        if (row.on_hold) continue;
        if (row.fraud_review) continue;
        if (row.payout <= 0) continue;
        fprintf(out, "%s,%s,%.2f\n",
                row.claim_reference, row.payee_account, row.payout);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

